/** The error every host-side failure throws: an engine call that did not complete, or a call on a
 *  disposed workbook (`StatusCode.BindingInvalidHandle`). Distinguish failures by `code`; there are no
 *  subclasses. An argument of the wrong type or range throws `TypeError` / `RangeError` instead.
 *
 *  `instanceof FormulonError` holds for the class imported from the same package that threw it. Code that
 *  may see errors from both `@libraz/formulon` and `@libraz/formulon-native` should test
 *  `e.name === 'FormulonError'`. */
export class FormulonError extends Error {
  constructor(code: StatusCode, message: string, context?: string);
  readonly name: 'FormulonError';
  /** What went wrong. */
  readonly code: StatusCode;
  /** Structured detail as space-separated `key=value` pairs (`sheet_index=5 sheet_count=1`); `''` when
   *  there is none. */
  readonly context: string;
}

/** Per-call telemetry returned by `Workbook.recalcParallel`. The five
 * scheduler counters are `uint64_t` in the C ABI but are exposed as
 * JavaScript `number` values. They are exact through
 * `Number.MAX_SAFE_INTEGER` (2^53 - 1). */
export interface ParallelRecalcStats {
  readonly cellsEvaluated: number;
  readonly sccsProcessed: number;
  readonly parallelSteps: number;
  readonly serialFallbackSteps: number;
  readonly cycleRecoveries: number;
  readonly workerThreadsStarted: number;
  readonly workerThreadsUsed: number;
}

/** A partial update. An omitted key leaves the field unchanged, `null` clears it and a value sets it;
 *  a field with no cleared form rejects `null` with a `TypeError`. */
export type Patch<T> = { [K in keyof T]?: T[K] | null };

/** A blank cell or argument. */
export interface BlankValue {
  readonly kind: typeof ValueKind.Blank;
}
/** A number. */
export interface NumberValue {
  readonly kind: typeof ValueKind.Number;
  readonly number: number;
}
/** A logical value. */
export interface BoolValue {
  readonly kind: typeof ValueKind.Bool;
  readonly boolean: boolean;
}
/** A text value. */
export interface TextValue {
  readonly kind: typeof ValueKind.Text;
  readonly text: string;
}
/** An Excel error value such as `#DIV/0!`. */
export interface ErrorValue {
  readonly kind: typeof ValueKind.Error;
  readonly errorCode: ErrorCode;
}
/** An array result; its elements are not carried on this value. */
export interface ArrayValue {
  readonly kind: typeof ValueKind.Array;
}
/** A reference result; the referenced cells are not carried on this value. */
export interface RefValue {
  readonly kind: typeof ValueKind.Ref;
}
/** A `LAMBDA` result. */
export interface LambdaValue {
  readonly kind: typeof ValueKind.Lambda;
}

/** A cell or formula value, discriminated by `kind`. Each member carries only
 *  the fields of its kind, so `if (v.kind === ValueKind.Number) v.number`
 *  narrows. A method taking a `Value` reads `kind` (required) and the field
 *  that kind needs, and throws `TypeError` when that field is missing or has
 *  the wrong type; `BoolValue.boolean` must be a `boolean`, not 0 / 1. */
export type Value = BlankValue | NumberValue | BoolValue | TextValue | ErrorValue | ArrayValue | RefValue | LambdaValue;

/**
 * Return type of `Workbook.evaluateFormulaArray(...)`: the whole multi-cell
 * result of an ad-hoc formula. `cells` is a `rows` x `cols` nested array in
 * row-major order (`cells[r][c]`); a scalar result is reported as a 1x1
 * array (`rows === cols === 1`).
 */
export interface EvalArray {
  readonly rows: number;
  readonly cols: number;
  readonly cells: Value[][];
}

/**
 * Return type of `Workbook.saveWithDiagnostics(format)`.
 *
 * A field means the same thing whichever container was written; where the
 * underlying event exists in only one container, the other simply never
 * raises it. Coverage is partial by design — an all-zero result means
 * none of the losses below occurred, not that nothing was logged.
 *
 * Summing these does NOT give "how many things did I lose":
 * `droppedPartCount` and `droppedRelationshipCount` both rise for one
 * dropped part.
 */
export interface SaveDiagnostics {
  /** The written workbook. */
  readonly bytes: Uint8Array;
  /** Formula cells emitted as cached literals. Always zero for XLSX. */
  readonly downgradedFormulaCount: number;
  /** Sheet features not lowered to records. Always zero for XLSX. */
  readonly deferredFeatureCount: number;
  /** Passthrough parts dropped for colliding with a generated path, or
   *  for two entries claiming one path. Both containers. */
  readonly droppedPartCount: number;
  /** Relationships dropped because their target part is gone. Both
   *  containers, at package / workbook / (XLSB) sheet scope. Rises with
   *  `droppedPartCount` for one dropped part — do not add them. */
  readonly droppedRelationshipCount: number;
  /** Tables emitted under a writer-assigned id. Always zero for XLSB. */
  readonly renumberedPartCount: number;
}

/**
 * Return type of `Workbook.getDiagnostics()`. Same contract as
 * `SaveDiagnostics`: one meaning per field across both containers,
 * partial coverage by design.
 */
export interface ReadDiagnostics {
  /** Formula cells whose stored formula could not be decoded. XLSB only. */
  readonly undecodedFormulaCount: number;
  /** Defined names skipped for the same reason. XLSB only. */
  readonly undecodedDefinedNameCount: number;
  /** Package parts whose content type could not be resolved, so they were
   *  not decoded. XLSB only — the XLSX reader keeps unmodelled parts as
   *  passthrough instead of dropping them. */
  readonly undecodedPartCount: number;
  /** Presentation-overlay entries dropped for an unusable reference: one
   *  per merge / hyperlink / data validation, one per conditional-format
   *  block (a block can carry several rules). XLSX only. */
  readonly skippedFeatureCount: number;
  /** Workbook parts whose content type was unrecognised. Max 1. XLSX only. */
  readonly unknownContentTypeCount: number;
}

/** Container format of a workbook, as `save` writes it. */
export const WorkbookFormat: Readonly<{
  Unknown: 0;
  Xlsx: 1;
  Xlsb: 2;
}>;
/** Union of the {@link WorkbookFormat} ordinals. */
export type WorkbookFormat = 0 | 1 | 2;

/** Return type of `Workbook.getCellAt(sheet, index)`. */
export interface CellEntry {
  row: number;
  col: number;
  /** Formula text spelled as `getFormula` returns it, or `null` for pure literals. */
  formula: string | null;
  value: Value;
}

/** A defined name, as `Workbook.getDefinedName` and `Workbook.listDefinedNames` return it. */
export interface DefinedName {
  name: string;
  /** Formula text spelled as `getFormula` spells formulas. */
  formula: string;
  /** -1 for workbook scope; otherwise a 0-based sheet index. */
  localSheetId: number;
  /** The note Excel shows in the Name Manager; empty when none. */
  comment: string;
  /** Whether the name is hidden from the Name Manager. */
  hidden: boolean;
}

/** A table column's totals-row function (`ST_TotalsRowFunction`). */
export type TableTotalsRowFunction =
  | 'none'
  | 'sum'
  | 'min'
  | 'max'
  | 'average'
  | 'count'
  | 'countNums'
  | 'stdDev'
  | 'var'
  | 'custom';

/** One column of `TableEntry.columns`. `totalsRowFormula` is the `custom`
 *  function's formula (no leading `=`), empty otherwise. */
export interface TableColumnEntry {
  name: string;
  totalsRowFunction: TableTotalsRowFunction;
  totalsRowLabel: string;
  totalsRowFormula: string;
}

/** Return type of `Workbook.getTable(index)`. `styleName` is empty without a
 *  style and may name a custom style (`getTableStyle`); `hasStyleInfo` is
 *  false when the table has no `<tableStyleInfo>` (the toggles then read
 *  false). The row counts are 0 or 1. */
export interface TableEntry {
  name: string;
  displayName: string;
  /** The table's sheet and range. */
  range: SheetRect;
  styleName: string;
  hasStyleInfo: boolean;
  showFirstColumn: boolean;
  showLastColumn: boolean;
  showRowStripes: boolean;
  showColumnStripes: boolean;
  headerRowCount: number;
  totalsRowCount: number;
  columns: TableColumnEntry[];
}

/** Authoring input for a worksheet table over `range`. `columns` must have
 * exactly one name per column of the range; `styleName` names a built-in
 * TableStyle or a custom style. A styled table starts with row stripes on and the other
 * toggles off; a supplied toggle overrides that (and, without `styleName`,
 * writes an unnamed style element). With `headerRow` (the default), the
 * caller still writes the header cells: Excel expects the first row of the
 * range to hold the column names. */
export interface TableInput {
  range: SheetRect;
  name: string;
  displayName?: string;
  columns: string[];
  styleName?: string;
  showFirstColumn?: boolean;
  showLastColumn?: boolean;
  showRowStripes?: boolean;
  showColumnStripes?: boolean;
  headerRow?: boolean;
  totalsRow?: boolean;
}

/** Partial table metadata update. Omitted fields preserve their existing
 * values; an empty `styleName` explicitly removes the table style, while a
 * new name keeps the four toggles. When omitted, `rect` also preserves the
 * current range. `headerRow` and
 * `totalsRow` update their flags only when supplied; turning `totalsRow` on
 * writes each column's totals cell on the last row of the range (see
 * `setTableColumnTotals`). `name` renames the table
 * (`displayName` follows it unless supplied), with `addTable`'s
 * uniqueness rule, and rewrites structured references to the old name in
 * cell, defined-name, conditional-format, validation and chart formulas; a
 * bare table name used as a reference is not rewritten. The update is
 * all-or-nothing. */
export interface TableUpdateInput {
  rect?: CellRect;
  name?: string;
  displayName?: string;
  styleName?: string;
  showFirstColumn?: boolean;
  showLastColumn?: boolean;
  showRowStripes?: boolean;
  showColumnStripes?: boolean;
  headerRow?: boolean;
  totalsRow?: boolean;
}

/** Totals-row settings of one table column (`setTableColumnTotals`).
 *  `function` defaults to `'none'`; `formula` is required for `'custom'`. */
export interface TableColumnTotalsInput {
  function?: TableTotalsRowFunction;
  label?: string;
  formula?: string;
}

/** A region of a custom table style (`ST_TableStyleType`). The PivotTable
 *  regions apply only to styles a PivotTable uses. */
export type TableStyleElementType =
  | 'wholeTable'
  | 'headerRow'
  | 'totalRow'
  | 'firstColumn'
  | 'lastColumn'
  | 'firstRowStripe'
  | 'secondRowStripe'
  | 'firstColumnStripe'
  | 'secondColumnStripe'
  | 'firstHeaderCell'
  | 'lastHeaderCell'
  | 'firstTotalCell'
  | 'lastTotalCell'
  | 'firstSubtotalColumn'
  | 'secondSubtotalColumn'
  | 'thirdSubtotalColumn'
  | 'firstSubtotalRow'
  | 'secondSubtotalRow'
  | 'thirdSubtotalRow'
  | 'blankRow'
  | 'firstColumnSubheading'
  | 'secondColumnSubheading'
  | 'thirdColumnSubheading'
  | 'firstRowSubheading'
  | 'secondRowSubheading'
  | 'thirdRowSubheading'
  | 'pageFieldLabels'
  | 'pageFieldValues';

/** One element of a custom table style. `size` is the stripe band size
 *  (default 1); `dxfId` indexes the differential formats (`addDxf`) and is
 *  absent for a region the style lists without formatting. */
export interface TableStyleElement {
  readonly type: TableStyleElementType;
  readonly size?: number;
  readonly dxfId?: number;
}

/** A custom table / PivotTable style (`setTableStyle`). `pivot` / `table`
 *  (default true) say which objects may use it. */
export interface TableStyle {
  readonly name: string;
  readonly pivot?: boolean;
  readonly table?: boolean;
  readonly elements?: TableStyleElement[];
}

/** Return type of `Workbook.getTableStyleDefaults()`; empty when unset. */
export interface TableStyleDefaults {
  readonly tableStyle: string;
  readonly pivotStyle: string;
}

/** PivotTable layout cell kind. */
export const PivotCellKind: Readonly<{
  Header: 0;
  RowLabel: 1;
  ColLabel: 2;
  Data: 3;
  RowSubtotal: 4;
  ColSubtotal: 5;
  GrandTotal: 6;
  Blank: 7;
}>;
/** Union of the {@link PivotCellKind} ordinals. */
export type PivotCellKind = 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;

/** One concrete cell in a projected PivotTable layout. */
export interface PivotCell {
  /** Absolute 0-based sheet row. */
  readonly row: number;
  /** Absolute 0-based sheet column. */
  readonly col: number;
  readonly value: Value;
  readonly kind: PivotCellKind;
  /** Header nesting depth; 0 for data cells. */
  readonly depth: number;
  /** Source field name when known. */
  readonly fieldName: string;
  /** The data field's `numFmtId` as a decimal string; empty when unset. */
  readonly numberFormat: string;
}

/** Return type of `Workbook.getPivotLayout(sheet, pivotIndex)`. */
export interface PivotLayout {
  /** The rectangle the layout covers in absolute sheet coordinates; `null` when it spans no cell. */
  readonly rect: CellRect | null;
  /** Sparse projected cells in row-major order. */
  readonly cells: ReadonlyArray<PivotCell>;
}

